using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.ARC.LogVisualizacionArchivos;using GraphApi.Services.ARC.LogVisualizacionArchivos;namespace GraphApi.Controllers.ARC.LogVisualizacionArchivos{    /// <summary>    /// Gestión de LogVisualizacionArchivos: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("ARC/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre LogVisualizacionArchivos")]    public class LogVisualizacionArchivosController : Controller    {        private readonly ILogVisualizacionArchivosService _objService;        public LogVisualizacionArchivosController(ILogVisualizacionArchivosService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los LogVisualizacionArchivos, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="logVisualizacionArchivoID">LogVisualizacionArchivoID</param>        /// <param name="archivoID">ArchivoID</param>        /// <param name="usuarioID">UsuarioID</param>        /// <param name="medio">Medio</param>        /// <param name="iPOrigen">IPOrigen</param>        /// <param name="userAgent">UserAgent</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de LogVisualizacionArchivos</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar LogVisualizacionArchivos",            Description = "Devuelve LogVisualizacionArchivos aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadLogVisualizacionArchivos>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadLogVisualizacionArchivos>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? logVisualizacionArchivoID,            [FromQuery] int? archivoID,            [FromQuery] int? usuarioID,            [FromQuery] string? medio,            [FromQuery] string? iPOrigen,            [FromQuery] string? userAgent,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetLogVisualizacionArchivosDynamic(                logVisualizacionArchivoID,                 archivoID,                 usuarioID,                 medio,                 iPOrigen,                 userAgent,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo LogVisualizacionArchivo.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del LogVisualizacionArchivo a crear.</param>        /// <returns>El LogVisualizacionArchivo recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear LogVisualizacionArchivos",            Description = "Inserta un nuevo LogVisualizacionArchivo en la base de datos."        )]        [ProducesResponseType(typeof(clReadLogVisualizacionArchivos), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadLogVisualizacionArchivos>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateLogVisualizacionArchivos objInput)        {            var vCreated = await _objService.CreateLogVisualizacionArchivos(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de LogVisualizacionArchivo.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del LogVisualizacionArchivo.</param>        /// <returns>El LogVisualizacionArchivo actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar LogVisualizacionArchivos",            Description = "Actualiza uno o varios campos de LogVisualizacionArchivo existente."        )]        [ProducesResponseType(typeof(clReadLogVisualizacionArchivos), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadLogVisualizacionArchivos>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateLogVisualizacionArchivos objInput)        {            var vUpdated = await _objService.UpdateLogVisualizacionArchivos(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un LogVisualizacionArchivo por su ID.        /// </summary>        [HttpDelete("{nLogVisualizacionArchivosID:int}")]        [SwaggerOperation(            Summary = "Eliminar LogVisualizacionArchivo",            Description = "Borra un LogVisualizacionArchivo si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nLogVisualizacionArchivosID)        {            var success = await _objService.DeleteLogVisualizacionArchivos(nLogVisualizacionArchivosID);            return success ? NoContent() : NotFound();        }    }}